UPDATE MOCK_KFTC_ACCOUNT
SET BALANCE = #{newBalance},
    UPDATED_AT = SYSTIMESTAMP
WHERE FINTECH_USE_NUM = #{fintechUseNum}
  AND BALANCE = #{expectedBalance}
  AND STATUS = 'ACTIVE'
  AND LEADER_YN = 'Y'
  AND #{newBalance} >= #{expectedBalance}

UPDATE GYE_ACCOUNT
SET ACCOUNT_STATUS = 'RETIRED'
WHERE GROUP_ID = #{groupId}
AND GYE_ACCOUNT_ID = #{currentAccountId}
AND ACCOUNT_STATUS = 'CURRENT'
